from flask import Flask, redirect, url_for

app = Flask(__name__)

# Словарь для хранения сопоставлений URL и функций
url_mapping = {}

def route(url):
    def decorator(func):
        # Добавляем функцию в словарь сопоставления
        url_mapping[url] = func
        # Декорируем функцию Flask
        app.add_url_rule(url, func.__name__, func)
        # Добавляем правило для перенаправления с косой чертой в конце
        if not url.endswith('/'):
            app.add_url_rule(url + '/', func.__name__ + '_redirect', lambda: redirect(url, code=301))
        return func
    return decorator

@app.route('/')
def index():
    return "Welcome to the Flask app!"

@route('/hello/<username>')
def hello(username):
    return f"Hello, {username}"

@route('/hello/<username>/')
def hello_redirect(username):
    return redirect(url_for('hello', username=username), code=301)

def escape(text):
    """Преобразует специальные символы в HTML-безопасные последовательности."""
    html_escape_table = {
        "&": "&amp;",
        '"': "&quot;",
        "'": "&apos;",
        ">": "&gt;",
        "<": "&lt;",
    }
    return "".join(html_escape_table.get(c, c) for c in text)

if __name__ == '__main__':
    app.run(debug=True)

